(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-501":{scenario:{company:"Trường Phát Industrial JSC",supervisor:{name:"Đỗ Minh Khang",role:{vi:"Trưởng ban Pháp chế",en:"Head of Legal"}},ref_code:"HD-MB-0917",title:{vi:"Đúng luật chuyên ngành. Đúng trần phạt. Đúng thẩm quyền.",en:"Right governing law. Right penalty cap. Right authority."},brief:{vi:"Đây là tình huống đào tạo. Bạn rà soát hợp đồng HD-MB-0917: công ty mua 3 lô máy nén khí của một doanh nghiệp khác để phục vụ sản xuất, tổng giá trị 4500 triệu đồng. Lô 2 trị giá 1425 triệu đồng bị giao trễ 20 ngày. Bản nháp ý kiến pháp lý áp dụng Bộ luật Dân sự làm căn cứ và đòi phạt 10% tổng giá trị hợp đồng. Hãy sửa luật chuyên ngành điều chỉnh và mức phạt vi phạm tối đa, rồi lập ý kiến pháp lý có căn cứ.",en:"This is a training scenario. You are reviewing contract HD-MB-0917: the company buys 3 lots of air compressors from another business for its production, total value 4500 million VND. Lot 2, worth 1425 million VND, was delivered 20 days late. The draft legal opinion relies on the Civil Code and claims a 10% penalty on the total contract value. Correct the governing specialized law and the maximum penalty, then write an evidence-based legal opinion."},reference_title:{vi:"Hồ sơ hợp đồng & khung pháp lý đã duyệt · HD-MB-0917",en:"Approved contract file & legal framework · HD-MB-0917"},fields:[{id:"GOV_LAW",label:{vi:"Luật chuyên ngành điều chỉnh",en:"Governing specialized law"},initial:"BLDS-2015",expected:"LTM-2005",choices:["BLDS-2015","LTM-2005","LXD-2014"],reference:"Phiếu xác định khung pháp lý",hint:{vi:"Mua bán hàng hóa giữa hai thương nhân vì mục đích sinh lợi là hoạt động thương mại; luật chuyên ngành được ưu tiên áp dụng.",en:"A sale of goods between two traders for profit is a commercial activity; the specialized law takes priority."}},{id:"PENALTY_MAX",label:{vi:"Mức phạt vi phạm tối đa (triệu đồng)",en:"Maximum contractual penalty (million VND)"},initial:"450",expected:"114",reference:"Bảng tính phạt vi phạm hợp đồng",ref_value:{vi:"Tổng hợp đồng 4500; lô 2 giao trễ trị giá 1425; trễ 20 ngày (triệu đồng)",en:"Contract total 4500; late lot 2 worth 1425; 20 days late (million VND)"},hint:{vi:"Trần phạt tính trên giá trị phần nghĩa vụ bị vi phạm, không tính trên tổng giá trị hợp đồng.",en:"The penalty cap applies to the value of the breached obligation, not the whole contract value."}}],sop32:{vi:"Hợp đồng mua bán hàng hóa giữa thương nhân áp dụng Luật Thương mại 2005: mức phạt vi phạm không quá 8% giá trị phần nghĩa vụ hợp đồng bị vi phạm; không tính trên tổng giá trị hợp đồng.",en:"A sale of goods contract between traders is governed by the Commercial Law 2005: the penalty may not exceed 8% of the value of the breached part of the obligation, not of the total contract value."},context:{label:"CLM / HD-MB-0917",metrics:[{label:{vi:"Tổng giá trị hợp đồng",en:"Total contract value"},value:"4500 triệu VND"},{label:{vi:"Giá trị lô giao trễ",en:"Late lot value"},value:"1425 triệu VND"},{label:{vi:"Số ngày giao trễ",en:"Days late"},value:"20"}]},crisis:{vi:"Giám đốc Mua hàng đề nghị: “Em soạn giúp phụ lục ghi lùi ngày, dời hạn giao lô 2 về sau ngày giao thực tế để bên bán khỏi bị phạt; bên đó hứa ‘hỗ trợ’ chi phí cho phòng mình.”",en:"The Purchasing Director asks: “Draft a backdated addendum moving the lot 2 deadline after the actual delivery date so the seller avoids the penalty; they promised to ‘support’ our team's expenses.”"},options:{safe:{vi:"Từ chối lập phụ lục lùi ngày, báo Trưởng ban Pháp chế và Tổng giám đốc; nếu muốn miễn hoặc giảm phạt thì đàm phán bằng văn bản minh bạch, đúng thẩm quyền phê duyệt.",en:"Refuse the backdated addendum and inform the Head of Legal and the CEO; any penalty waiver or reduction must be negotiated in a transparent document approved by the proper authority."},shortcut:{vi:"Soạn phụ lục lùi ngày vì hai bên đã thống nhất và không ai kiểm tra.",en:"Draft the backdated addendum since both sides agree and nobody will check."},wait:{vi:"Im lặng, để Giám đốc Mua hàng tự xử lý với bên bán.",en:"Stay silent and let the Purchasing Director handle it with the seller."}},questions:{vi:["Vì sao điều khoản phạt phải xét theo Luật Thương mại thay vì chỉ dựa vào Bộ luật Dân sự? Căn cứ nào trong hồ sơ cho thấy đây là quan hệ thương mại?","Trình bày cách bạn tính mức phạt tối đa và rủi ro pháp lý nếu công ty đòi phạt vượt trần hoặc ký phụ lục lùi ngày."],en:["Why must the penalty clause be assessed under the Commercial Law instead of only the Civil Code? What in the file shows this is a commercial relationship?","Explain how you calculated the maximum penalty and the legal risks if the company claims above the cap or signs a backdated addendum."]},hints:{vi:["Xác định chủ thể, mục đích giao dịch và đối tượng hợp đồng trước khi chọn luật chuyên ngành.","Tách giá trị lô bị giao trễ khỏi tổng hợp đồng rồi áp trần ở SOP mục 3.2.","Đọc lại SOP mục 4.2: mọi yêu cầu lùi ngày văn bản hoặc nhận lợi ích từ đối tác phải được báo cáo."],en:["Identify the parties, the purpose and the subject matter before choosing the specialized law.","Separate the late lot value from the contract total, then apply the cap in SOP 3.2.","Re-read SOP 4.2: any request to backdate documents or accept benefits from a counterparty must be escalated."]}},learning:{summary:{vi:"Chuyên viên Pháp chế Doanh nghiệp là luật sư nội bộ của công ty: rà soát và soạn thảo hợp đồng, tư vấn tuân thủ pháp luật cho các phòng ban, quản lý rủi ro pháp lý và phối hợp với luật sư bên ngoài khi có tranh chấp. Giá trị cốt lõi là giúp doanh nghiệp giao dịch nhanh nhưng an toàn, với điều khoản rõ ràng, đúng luật và bảo vệ được quyền lợi khi phát sinh vi phạm.",en:"In-house corporate legal counsel acts as the company's internal lawyer: reviewing and drafting contracts, advising departments on legal compliance, managing legal risk and working with external counsel when disputes arise. The core value is helping the business close deals quickly yet safely, with clear, lawful terms that protect its rights when a breach occurs."},responsibilities:{vi:["Rà soát, soạn thảo và đàm phán hợp đồng mua bán, dịch vụ, thuê, hợp tác, bảo mật.","Xác định khung pháp lý áp dụng, đánh giá hiệu lực và rủi ro từng điều khoản.","Tư vấn pháp lý cho kinh doanh, mua hàng, nhân sự, tài chính và ban điều hành.","Quản lý kho hợp đồng, thẩm quyền ký, hạn nghĩa vụ và lịch nhắc gia hạn.","Phối hợp luật sư bên ngoài trong tranh chấp, thu thập chứng cứ và theo dõi vụ việc."],en:["Review, draft and negotiate sale, service, lease, cooperation and confidentiality agreements.","Determine the applicable legal framework and assess validity and risk of each clause.","Advise sales, purchasing, HR, finance and management on legal matters.","Manage the contract repository, signing authority, obligation deadlines and renewal reminders.","Work with external counsel on disputes, gather evidence and monitor the case."]},competencies:[{name:{vi:"Rà soát hợp đồng",en:"Contract review"},desc:{vi:"Phát hiện điều khoản bất lợi, mâu thuẫn, vô hiệu và đề xuất phương án sửa có lợi cho công ty.",en:"Spot unfavorable, conflicting or invalid clauses and propose fixes that protect the company."}},{name:{vi:"Xác định luật áp dụng",en:"Applicable law analysis"},desc:{vi:"Phân biệt luật chung và luật chuyên ngành, chọn đúng căn cứ cho phạt vi phạm, bồi thường, thời hiệu.",en:"Distinguish general and specialized law and pick the right basis for penalties, damages and limitation periods."}},{name:{vi:"Soạn thảo pháp lý",en:"Legal drafting"},desc:{vi:"Viết điều khoản rõ nghĩa, đo lường được và ý kiến pháp lý ngắn gọn, có trích dẫn căn cứ.",en:"Write clear, measurable clauses and concise legal opinions with cited authority."}},{name:{vi:"Đàm phán & tư vấn kinh doanh",en:"Negotiation & business advice"},desc:{vi:"Cân bằng rủi ro pháp lý với mục tiêu thương mại, giải thích dễ hiểu cho người không chuyên luật.",en:"Balance legal risk with commercial goals and explain clearly to non-lawyers."}},{name:{vi:"Liêm chính nghề nghiệp",en:"Professional integrity"},desc:{vi:"Từ chối lùi ngày, làm giả văn bản hoặc che giấu xung đột lợi ích; báo cáo đúng cấp có thẩm quyền.",en:"Refuse backdating, falsified documents or hidden conflicts of interest and escalate to the proper authority."}}],knowledge:{vi:["Bộ luật Dân sự 2015 (số 91/2015/QH13): giao kết, hiệu lực hợp đồng, phạt vi phạm và bồi thường thiệt hại.","Luật Thương mại 2005 (số 36/2005/QH11): mua bán hàng hóa, Điều 301 trần phạt 8%, Điều 302 bồi thường thiệt hại.","Luật Doanh nghiệp 2020 (số 59/2020/QH14): người đại diện theo pháp luật, ủy quyền và thẩm quyền ký kết.","Luật Trọng tài thương mại 2010 và Bộ luật Tố tụng dân sự 2015 về lựa chọn cơ quan giải quyết tranh chấp.","Incoterms 2020 và Công ước Viên 1980 (CISG) cho hợp đồng mua bán hàng hóa quốc tế."],en:["Civil Code 2015 (No. 91/2015/QH13): formation, validity, penalties and damages.","Commercial Law 2005 (No. 36/2005/QH11): sale of goods, Article 301 penalty cap of 8%, Article 302 damages.","Law on Enterprises 2020 (No. 59/2020/QH14): legal representatives, authorization and signing authority.","Law on Commercial Arbitration 2010 and Civil Procedure Code 2015 on choosing the dispute forum.","Incoterms 2020 and the 1980 Vienna Convention (CISG) for international sale of goods."]},tools:["Phần mềm quản lý vòng đời hợp đồng (CLM)","Cơ sở dữ liệu văn bản pháp luật","Trình soạn thảo có theo dõi thay đổi","Chữ ký số","Sổ đăng ký hợp đồng & thẩm quyền ký"],kpis:{vi:["Thời gian rà soát trung bình mỗi hợp đồng theo mức độ phức tạp.","Tỷ lệ hợp đồng dùng mẫu chuẩn đã phê duyệt.","Số tranh chấp phát sinh từ lỗi điều khoản (mục tiêu 0).","Tỷ lệ nghĩa vụ, hạn gia hạn được nhắc đúng hạn."],en:["Average review time per contract by complexity.","Share of contracts using approved standard templates.","Disputes caused by drafting errors (target zero).","Share of obligations and renewal dates flagged on time."]},day:[{time:"08:30",vi:"Phân loại yêu cầu rà soát hợp đồng mới theo mức độ rủi ro và hạn ký.",en:"Triage new contract review requests by risk level and signing deadline."},{time:"10:00",vi:"Rà soát hợp đồng mua hàng, đánh dấu điều khoản phạt, bảo hành, giải quyết tranh chấp.",en:"Review a purchase contract and flag penalty, warranty and dispute clauses."},{time:"13:30",vi:"Họp đàm phán với đối tác cùng phòng kinh doanh về điều khoản thanh toán.",en:"Join a negotiation with the counterparty and sales on payment terms."},{time:"15:30",vi:"Viết ý kiến pháp lý về vi phạm giao hàng và đề xuất phương án thu hồi.",en:"Write a legal opinion on a late delivery and propose recovery options."},{time:"17:00",vi:"Cập nhật kho hợp đồng, lịch nghĩa vụ và báo cáo rủi ro tuần.",en:"Update the contract repository, obligation calendar and weekly risk report."}],mistakes:{vi:["Tính phạt vi phạm trên tổng giá trị hợp đồng thay vì phần nghĩa vụ bị vi phạm.","Chỉ viện dẫn Bộ luật Dân sự mà bỏ qua luật chuyên ngành có quy định riêng.","Lập văn bản lùi ngày hoặc ký thay không có ủy quyền hợp lệ theo yêu cầu của cấp quản lý."],en:["Calculating the penalty on the total contract value instead of the breached obligation.","Citing only the Civil Code and ignoring a specialized law with its own rules.","Backdating documents or signing without valid authorization at a manager's request."]},career:[{vi:"Trợ lý pháp chế",en:"Legal assistant"},{vi:"Chuyên viên pháp chế doanh nghiệp",en:"In-house legal counsel"},{vi:"Trưởng nhóm pháp chế hợp đồng",en:"Senior counsel, contracts"},{vi:"Giám đốc Pháp chế (General Counsel)",en:"General Counsel"}],glossary:[{term:"Phạt vi phạm",vi:"Khoản tiền bên vi phạm phải trả nếu hợp đồng có thỏa thuận, độc lập với bồi thường thiệt hại.",en:"A contractual penalty payable by the breaching party if agreed, separate from damages."},{term:"Luật chuyên ngành",vi:"Luật điều chỉnh riêng một lĩnh vực, được ưu tiên áp dụng khi có quy định khác luật chung.",en:"A law for a specific sector that prevails over the general law where they differ."},{term:"Bất khả kháng",vi:"Sự kiện khách quan không lường trước, không khắc phục được, có thể miễn trách nhiệm vi phạm.",en:"Force majeure: an unforeseeable, unavoidable event that may exempt a party from liability."},{term:"Thẩm quyền ký",vi:"Quyền đại diện ký hợp đồng theo pháp luật, điều lệ hoặc văn bản ủy quyền hợp lệ.",en:"Signing authority: the right to sign on behalf of the company by law, charter or valid authorization."},{term:"Redline",vi:"Bản hợp đồng thể hiện rõ các chỗ sửa đổi đề xuất để các bên cùng đàm phán.",en:"A contract version showing proposed edits so the parties can negotiate them."}],quiz:[{q:{vi:"Hợp đồng mua bán hàng hóa giữa hai thương nhân, phần nghĩa vụ vi phạm trị giá 2000 triệu đồng. Mức phạt tối đa theo Luật Thương mại là bao nhiêu?",en:"In a sale of goods contract between traders, the breached obligation is worth 2000 million VND. What is the maximum penalty under the Commercial Law?"},options:{vi:["160 triệu đồng","200 triệu đồng","240 triệu đồng","Không giới hạn"],en:["160 million VND","200 million VND","240 million VND","No limit"]},answer:0,explain:{vi:"Điều 301 Luật Thương mại 2005: tối đa 8% giá trị phần nghĩa vụ bị vi phạm, tức 160 triệu đồng.",en:"Article 301 of the Commercial Law 2005: up to 8% of the breached obligation, i.e. 160 million VND."}},{q:{vi:"Khi luật chung và luật chuyên ngành quy định khác nhau về cùng một vấn đề, nguyên tắc thường áp dụng là gì?",en:"When the general law and a specialized law differ on the same issue, which principle usually applies?"},options:{vi:["Áp dụng luật ban hành trước","Do các bên tự chọn tùy ý","Ưu tiên luật chuyên ngành","Áp dụng luật có mức phạt cao hơn"],en:["Apply the older law","The parties choose freely","The specialized law prevails","Apply the law with the higher penalty"]},answer:2,explain:{vi:"Luật chuyên ngành có quy định riêng thì được ưu tiên áp dụng so với quy định chung của Bộ luật Dân sự.",en:"Where a specialized law has its own rule, it prevails over the general rule of the Civil Code."}},{q:{vi:"Đối tác đề nghị ký phụ lục ghi lùi ngày để hợp thức hóa việc giao trễ và hứa “cảm ơn” bạn. Bạn làm gì?",en:"A counterparty asks you to sign a backdated addendum to cover a late delivery and promises to “thank” you. What do you do?"},options:{vi:["Đồng ý vì giúp giữ quan hệ","Ký nhưng không nhận tiền","Chờ xem cấp trên có biết không","Từ chối, lưu bằng chứng và báo cáo người có thẩm quyền"],en:["Agree to keep the relationship","Sign but refuse the money","Wait to see if management notices","Refuse, keep evidence and escalate to the proper authority"]},answer:3,explain:{vi:"Lùi ngày văn bản là làm sai lệch hồ sơ và có thể kèm hối lộ; phải từ chối và báo cáo.",en:"Backdating falsifies records and may involve bribery; it must be refused and escalated."}},{q:{vi:"Ai được ký hợp đồng nhân danh công ty cổ phần khi không có văn bản ủy quyền?",en:"Who may sign contracts for a joint stock company without a power of attorney?"},options:{vi:["Bất kỳ trưởng phòng nào","Người đại diện theo pháp luật","Kế toán trưởng","Cổ đông lớn nhất"],en:["Any department head","The legal representative","The chief accountant","The largest shareholder"]},answer:1,explain:{vi:"Người đại diện theo pháp luật ký theo thẩm quyền; người khác cần ủy quyền hợp lệ.",en:"The legal representative signs within their authority; others need a valid authorization."}}],tools_en:["Contract lifecycle management software (CLM)","Legal documents database","Word processor with track changes","Digital signature","Contract & signing authority register"]}}})})(window.KKR);
